export interface Spell5e {
  id: string;
  name: string;
  level: number;
  school: "Evocation" | "Abjuration" | "Conjuration" | "Divination" | "Enchantment" | "Illusion" | "Necromancy" | "Transmutation";
  castingTime: string;
  range: string;
  components: string;
  duration: string;
  concentration: boolean;
  ritual: boolean;
  classes: string[];
  isAttack?: boolean;
  saveStat?: "str" | "dex" | "con" | "int" | "wis" | "cha";
  damageDice?: string;
  damageType?: string;
  healingDice?: string;
  description: string;
}

type School = Spell5e["school"];

function s(
  id: string,
  name: string,
  level: number,
  school: School,
  castingTime: string,
  range: string,
  components: string,
  duration: string,
  classes: string[],
  description: string,
  opts: Partial<Omit<Spell5e, "id" | "name" | "level" | "school" | "castingTime" | "range" | "components" | "duration" | "classes" | "description">> = {}
): Spell5e {
  return {
    id,
    name,
    level,
    school,
    castingTime,
    range,
    components,
    duration,
    concentration: Boolean(opts.concentration),
    ritual: Boolean(opts.ritual),
    classes,
    description,
    ...(opts.isAttack ? { isAttack: true } : {}),
    ...(opts.saveStat ? { saveStat: opts.saveStat } : {}),
    ...(opts.damageDice ? { damageDice: opts.damageDice } : {}),
    ...(opts.damageType ? { damageType: opts.damageType } : {}),
    ...(opts.healingDice ? { healingDice: opts.healingDice } : {}),
  };
}

